insert into public.relief_rules (ya, version, rules, note, source_url, is_active) values (2025, 1, '[{"id":"lifestyle","name":"Lifestyle","limit":2500,"tone":"indigo","icon":"bag","covers":"Books and e-books, smartphone, tablet or computer, internet bill in your name, upskilling course fees.","evidence":"Receipt or invoice in your own name. For internet, the monthly bill."},{"id":"sports","name":"Sports extra","limit":1000,"tone":"mint","icon":"ball","covers":"Sports equipment, court or facility rental, competition entry fees, gym membership and training fees for you, spouse, child or parents.","evidence":"Receipt from the shop, facility or organiser."},{"id":"medical","name":"Medical expenses","limit":10000,"tone":"rose","icon":"medkit","covers":"Serious disease and fertility treatment, vaccination, dental, full check-ups, self-test kits, mental health and child learning-disability care for you, spouse or child.","evidence":"Clinic or hospital receipt. Serious illness needs a doctor''s certification.","sub":[{"id":"vaccine","name":"Vaccination","limit":1000},{"id":"dental","name":"Dental","limit":1000},{"id":"checkup","name":"Check-up, self-test and mental health","limit":1000}]},{"id":"childcare","name":"Childcare & kindergarten","limit":3000,"tone":"sun","icon":"smile","needs":"kids","covers":"Fees to a registered childcare centre or kindergarten for a child aged 6 and below.","evidence":"Official receipt showing the centre''s registration number."},{"id":"breastfeeding","name":"Breastfeeding equipment","limit":1000,"tone":"rose","icon":"drop","needs":"kids","covers":"Breast pump, cooler bag and milk storage for a child aged 2 and below. Claimable once every 2 YAs.","evidence":"Receipt for the equipment."},{"id":"education","name":"Education fees (self)","limit":7000,"tone":"sky","icon":"cap","covers":"Degree, master''s or doctorate fees, or recognised certificate courses. Upskilling courses up to RM2,000.","evidence":"Fee receipt from the institution.","sub":[{"id":"upskill","name":"Upskilling courses","limit":2000}]},{"id":"parents","name":"Parents'' medical & care","limit":8000,"tone":"rose","icon":"heart","needs":"parents","covers":"Medical treatment, dental and care for your parents or grandparents. Check-ups and vaccination up to RM1,000.","evidence":"Receipt naming the parent as patient.","sub":[{"id":"pcheckup","name":"Check-up and vaccination","limit":1000}]},{"id":"insurance","name":"Education & medical insurance","limit":4000,"tone":"sky","icon":"shield","covers":"Premiums for medical or education insurance for you, spouse or child.","evidence":"Annual premium statement from the insurer."},{"id":"life","name":"Life insurance & EPF","limit":7000,"tone":"indigo","icon":"umbrella","covers":"EPF contributions up to RM4,000 plus life insurance or takaful up to RM3,000.","evidence":"EPF statement and insurer premium statement.","sub":[{"id":"epf","name":"EPF","limit":4000},{"id":"lifeins","name":"Life insurance or takaful","limit":3000}]},{"id":"prs","name":"PRS & deferred annuity","limit":3000,"tone":"mint","icon":"piggy","covers":"Private Retirement Scheme contributions.","evidence":"PRS provider statement."},{"id":"sspn","name":"SSPN savings","limit":8000,"tone":"sun","icon":"piggy","needs":"kids","covers":"Net deposits into SSPN for your child.","evidence":"SSPN annual statement."},{"id":"socso","name":"SOCSO / PERKESO","limit":350,"tone":"sky","icon":"shield","covers":"Your employee SOCSO contributions.","evidence":"Payslip or EA form."},{"id":"green","name":"EV charging & green","limit":2500,"tone":"mint","icon":"bolt","covers":"EV charger installation, rental or subscription, food-waste composting machine or grinder, home CCTV.","evidence":"Receipt for the equipment or charging subscription."},{"id":"zakat","name":"Zakat / Fitrah rebate","limit":null,"kind":"rebate","tone":"peach","icon":"moon","covers":"Rebate, not relief: the full amount paid to a state religious authority comes off your tax payable, up to the tax you owe.","evidence":"Official receipt from the zakat centre (e.g. LZS, PPZ-MAIWP)."}]'::jsonb, 'Initial rules from PwC Malaysian Tax Booklet 2026/2027', 'https://www.pwc.com/my/en/publications/mtb/personal-income-tax.html', true) on conflict do nothing;
